function articleCards(){return articles.map(a=>'<a class="journal-card" href="#/article/'+a.id+'"><img src="assets/'+a.img+'" alt="" loading="lazy"><div class="row between muted"><span>'+tr(...a.category)+'</span><span>'+a.date+'</span></div><h3>'+tr(...a.title)+'</h3></a>').join('')}
function newsletter(){return '<div class="newsletter"><div><div class="eyebrow">'+tr('MS LABi kirjad','Письма MS LAB')+'</div><h2 style="margin-top:20px">'+tr('Hea järgmine samm.<br>Otse sinu postkasti.','Ваш следующий шаг.<br>В вашем почтовом ящике.')+'</h2><p>'+tr('Uued koolitused, kasulikud mõtted ja '+state.discount+'% tervitussoodustus sinu esimesele koolitusele.','Новые курсы, полезные идеи и приветственная скидка '+state.discount+'% на первый курс.')+'</p></div><div id="newsletter-state">'+(state.newsletter===0?'<form id="newsletter-form"><label class="text-small" for="newsletter-email">'+tr('Sinu e-post','Ваш email')+'</label><div class="email-row" style="margin-top:10px"><input id="newsletter-email" type="email" placeholder="nimi@e-post.ee" required autocomplete="email"><button class="btn" type="submit">'+tr('Liitu','Подписаться')+icon('arrow')+'</button></div><label class="check"><input type="checkbox" required><span>'+tr('Soovin saada MS LABi uudiskirju. Saan igal ajal loobuda.','Я хочу получать рассылку MS LAB. Можно отписаться в любой момент.')+'</span></label></form>':state.newsletter===1?'<h3>'+tr('Kinnita oma e-post','Подтвердите email')+'</h3><p>'+tr('Päris teenuses saabuks kinnituskiri. Siin saad selle sammu läbi proovida.','В реальном сервисе придёт письмо. Здесь можно попробовать этот шаг.')+'</p><button class="demo-action" style="margin-top:15px" data-action="confirm-newsletter">'+tr('Simuleeri e-posti kinnitamist','Симулировать подтверждение')+'</button>':'<h3>'+tr('Tere tulemast MS LABi!','Добро пожаловать в MS LAB!')+'</h3><p>'+tr('Sinu näidiskood on','Ваш пример кода')+' <strong>TERE10</strong> · −'+state.discount+'%</p><button class="link" data-action="copy-code">'+tr('Kopeeri kood','Копировать код')+icon('up')+'</button>')+'</div></div>'}
function home(){return hero()+'<div class="principles wrap"><div class="principle">'+icon('book')+tr('Teadmised, millele saad toetuda','Знания, на которые можно опереться')+'</div><div class="principle">'+icon('flower')+tr('Praktika päris modellidega','Практика на реальных моделях')+'</div><div class="principle">'+icon('award')+tr('Sinu arengut toetav juhendamine','Поддержка вашего развития')+'</div></div><section class="intro wrap"><div class="eyebrow">'+tr('Rohkem kui koolitus','Больше, чем курс')+'</div><div><h2>'+tr('Hea algus annab oskused.<br>Õige tugi aitab sul kasvada.','Хороший старт даёт навыки.<br>Поддержка помогает расти.')+'</h2><p class="muted">'+tr('Alustad uut teekonda või lihvid oma käekirja — MS LABis õpid läbimõeldult, praktiliselt ja endale sobivas tempos.','Начинаете новый путь или совершенствуете свой почерк — в MS LAB вы учитесь осознанно, на практике и в своём темпе.')+'</p></div></section><section class="courses-home"><div class="section-heading"><div><div class="eyebrow">'+tr('Õpi. Arene. Loo.','Учись. Развивайся. Создавай.')+'</div><h2>'+tr('Sinu järgmine oskus.','Ваш следующий навык.')+'</h2></div><a href="#/courses" class="link">'+tr('Kõik koolitused','Все курсы')+icon('up')+'</a></div><div class="course-grid">'+courses.slice(0,3).map(courseCard).join('')+'</div>'+sample()+'</section><section class="section wrap"><div class="section-heading"><div><div class="eyebrow">'+tr('Kohtume koolitusel','Встретимся на курсе')+'</div><h2>'+tr('Leia oma aeg ja koht.','Найдите своё время и место.')+'</h2></div><a class="link" href="#/calendar">'+tr('Kogu kalender','Всё расписание')+icon('up')+'</a></div><div class="calendar-list">'+sessionRows(3)+'</div>'+sample()+'</section>'+teacher()+'<section class="section wrap">'+practicePanel()+'</section><section class="section wrap"><div class="section-heading"><div><div class="eyebrow">'+tr('Uudised ja inspiratsioon','Новости и вдохновение')+'</div><h2>'+tr('Mõtteid sinu teekonnale.','Идеи для вашего пути.')+'</h2></div><a class="link" href="#/news">'+tr('Kõik lood','Все статьи')+icon('up')+'</a></div><div class="journal-grid">'+articleCards()+'</div></section><section class="section wrap"><div class="review-empty"><div><h3>'+tr('Õpilaste lood','Истории учеников')+'</h3><p>'+tr('Siia jõuavad õpilaste kogemused pärast nende kinnitamist.','Здесь появятся отзывы учеников после модерации.')+'</p></div><button class="btn secondary" data-action="review">'+tr('Jaga oma kogemust','Поделиться опытом')+'</button></div></section><section class="section wrap">'+newsletter()+'</section>'}
function catalogue(){return '<div class="page-head wrap"><div class="eyebrow">'+tr('Sinu õpiteekond','Ваше обучение')+'</div><h1>'+tr('Oskused, mis jäävad sinuga.','Навыки, которые остаются с вами.')+'</h1><p>'+tr('Vali esimene samm või järgmine väljakutse. Õpi veebis, kohapeal või ühenda mõlema eelised.','Выберите первый шаг или новый вызов. Учитесь онлайн, очно или сочетайте оба формата.')+'</p></div><section class="wrap catalogue"><div class="filter-bar"><div class="pills">'+['all','online','contact','hybrid'].map(f=>'<button class="pill '+(state.filter===f?'active':'')+'" data-action="filter" data-format="'+f+'">'+(f==='all'?tr('Kõik koolitused','Все курсы'):fmt(f))+'</button>').join('')+'</div><label class="search">'+icon('search')+'<input id="course-search" value="'+esc(state.search)+'" placeholder="'+tr('Otsi koolitust','Поиск курсов')+'" aria-label="'+tr('Otsi koolitust','Поиск курсов')+'"></label></div><div id="course-results" class="course-grid">'+filteredCourses()+'</div>'+sample()+'</section>'}
function filteredCourses(){const cs=courses.filter(c=>(state.filter==='all'||c.format===state.filter)&&name(c.id).toLowerCase().includes(state.search.toLowerCase()));return cs.length?cs.map(courseCard).join(''):'<div class="empty"><h3>'+tr('Sobivat koolitust ei leitud','Курсы не найдены')+'</h3><p>'+tr('Muuda otsingut või vaata kõiki koolitusi.','Измените поиск или посмотрите все курсы.')+'</p><button class="btn secondary" style="margin-top:20px" data-action="clear-filters">'+tr('Lähtesta filtrid','Сбросить фильтры')+'</button></div>'}
const offerPrice=(id,f)=>id==='brow'?({online:190,hybrid:state.customPrice,contact:350}[f]):course(id).price;
function detail(id){const c=course(id),price=offerPrice(c.id,state.format);return '<div class="page-head wrap" style="padding-bottom:28px"><div class="breadcrumb"><a href="#/">'+tr('Avaleht','Главная')+'</a> / <a href="#/courses">'+tr('Koolitused','Курсы')+'</a> / <span>'+name(c.id)+'</span></div></div><section class="wrap detail-page"><div class="course-detail"><div class="detail-image"><img src="assets/'+c.image+'" alt="'+name(c.id)+'"><div class="tags"><span class="tag">'+tr('Sinu uus algus','Ваше новое начало')+'</span><span class="tag">MS LAB</span></div></div><div class="detail-info"><div class="tags"><span class="tag">'+tr('Algajale','Для начинающих')+'</span><span class="tag">ET</span></div><h1>'+name(c.id)+'</h1><p>'+tr('Teooriast esimese iseseisva tulemuseni. Õpi samm-sammult, harjuta teadlikult ja leia kindlus oma kätes.','От теории до первого самостоятельного результата. Учитесь шаг за шагом и обретайте уверенность в своих руках.')+'</p><div class="format-list" role="group" aria-label="'+tr('Õppevorm','Формат обучения')+'">'+(c.id==='brow'?['online','hybrid','contact']:[c.format]).map(f=>'<button class="format-option '+(state.format===f?'active':'')+'" data-action="format" data-format="'+f+'" aria-pressed="'+(state.format===f)+'"><span class="radio-dot"></span><span class="label"><strong>'+fmt(f)+'</strong><small>'+({online:tr('Õpi veebis omas tempos','Онлайн в своём темпе'),hybrid:tr('E-õpe + juhendatud kontaktpäev','Онлайн + очный практический день'),contact:tr('Õpi koos koolitajaga kohapeal','Учитесь очно с преподавателем')})[f]+'</small></span><strong>'+money(offerPrice(c.id,f))+'</strong></button>').join('')+'</div>'+(state.format!=='online'?'<label class="text-small">'+tr('Vali kontaktpäev','Выберите очный день')+'</label><div class="date-chips">'+['14.11.2026','12.12.2026'].map((d,i)=>'<button class="pill '+(state.date===d?'active':'')+'" data-action="date" data-date="'+d+'">'+d+' · '+(i?'Pärnu':'Tallinn')+'</button>').join('')+'<button class="pill" disabled>05.12 · '+tr('Täis','Мест нет')+'</button></div>':'')+'<div class="detail-facts"><div><span>'+tr('Õppekeel','Язык курса')+'</span><strong>'+tr('Eesti keel','Эстонский')+'</strong></div><div><span>'+tr('Ligipääs','Доступ')+'</span><strong>'+state.accessMonths+tr(' kuud*',' месяцев*')+'</strong></div><div><span>'+tr('Tasumine','Оплата')+'</span><strong>100% / 50%</strong></div></div><button class="btn full" data-action="add-cart" data-id="'+c.id+'">'+tr('Lisa ostukorvi','В корзину')+' · '+money(price)+icon('bag')+'</button><div class="row between" style="margin-top:16px"><span class="text-small muted">'+tr('* Näidistingimused','* Пример условий')+'</span><button class="link" data-action="share">'+tr('Jaga koolitust','Поделиться')+icon('up')+'</button></div>'+sample()+'</div></div><div class="detail-bottom"><div><h2>'+tr('Pärast koolitust oskad','После курса вы сможете')+'</h2><ul class="check-list"><li>'+tr('Analüüsida kliendi eripärasid ja valida sobiva tehnika.','Анализировать особенности клиента и выбирать технику.')+'</li><li>'+tr('Planeerida tööetappe ja kasutada töövahendeid teadlikult.','Планировать этапы работы и осознанно применять инструменты.')+'</li><li>'+tr('Rakendada õpitut juhendatud praktikas.','Применять знания на практике под руководством.')+'</li><li>'+tr('Selgitada kliendile järelhooldust.','Объяснять клиенту последующий уход.')+'</li></ul><div class="notice" style="margin-top:25px">'+tr('Tunnistuse saamiseks tuleb täita koolituse hindamistingimused. Näites: test ja koolitaja kinnitatud praktiline töö.','Для получения свидетельства нужно выполнить условия оценки. В примере: тест и практика, подтверждённая преподавателем.')+'</div></div><div><h2>'+tr('Sinu õpiteekond','Ваша программа')+'</h2><div class="accordion">'+[tr('Vundament: anatoomia ja hügieen','Основа: анатомия и гигиена'),tr('Analüüs ja tehnika valik','Анализ и выбор техники'),tr('Töövahendid ja protseduur','Инструменты и процедура'),tr('Praktika, test ja tagasiside','Практика, тест и обратная связь')].map((x,i)=>'<details><summary><span>'+String(i+1).padStart(2,'0')+' &nbsp; '+x+'</span></summary><p>'+tr('Videoõpe, selgitavad õppematerjalid ja praktilised ülesanded. Täpse õppekava kinnitab koolitaja enne avaldamist.','Видеоуроки, учебные материалы и практические задания. Полную программу преподаватель утвердит перед публикацией.')+'</p></details>').join('')+'</div></div></div><div class="sticky-purchase"><div><strong>'+fmt(state.format)+'</strong><small>'+money(price)+'</small></div><button class="btn" data-action="add-cart" data-id="'+c.id+'">'+tr('Lisa ostukorvi','В корзину')+icon('bag')+'</button></div></section>'}
function calendar(){return '<div class="page-head wrap"><div class="eyebrow">'+tr('Koolituskalender','Расписание курсов')+'</div><h1>'+tr('Võta aega oma arenguks.','Найдите время для развития.')+'</h1><p>'+tr('Leia sobiv koolituspäev Tallinnas, Pärnus või Tartus. Kõik kellaajad on Eesti aja järgi.','Выберите день обучения в Таллинне, Пярну или Тарту. Время указано по Эстонии.')+'</p></div><section class="wrap section" style="padding-top:0"><div class="pills">'+['all','Tallinn','Pärnu','Tartu'].map(c=>'<button class="pill '+(state.city===c?'active':'')+'" data-action="city" data-city="'+c+'">'+(c==='all'?tr('Kõik linnad','Все города'):c)+'</button>').join('')+'</div><div class="calendar-list">'+sessionRows()+'</div>'+sample()+'</section>'}
function practice(){return '<div class="page-head wrap"><div class="eyebrow">'+tr('Praktika MS LABis','Практика в MS LAB')+'</div><h1>'+tr('Sinu areng.<br>Kogu minu tähelepanu.','Ваше развитие.<br>Всё моё внимание.')+'</h1><p>'+tr('Üks-ühele praktikapäev, kus saad küsimustele vastused, lihvid tehnikat ja harjutad rahulikult. Vali pakett ning lepime koos aja kokku.','Индивидуальный день практики: ответы на вопросы, работа над техникой и спокойное обучение. Выберите пакет, а время согласуем вместе.')+'</p></div><section class="wrap section" style="padding-top:0">'+practicePanel(true)+sample()+'<div id="registration" class="registration">'+(state.practiceSent?'<div class="success-block card"><div class="success-icon">✓</div><h2>'+tr('Taotlus on saadetud.','Заявка отправлена.')+'</h2><p class="muted">'+tr('Näidistaotlus on salvestatud ainult selles prototüübis. Maria kinnitab aja eraldi; praegu ei ole kohtumine broneeritud.','Пример заявки сохранён только в этом прототипе. Мария отдельно подтвердит время; запись пока не подтверждена.')+'</p><button class="btn secondary" style="margin-top:25px" data-action="new-practice">'+tr('Muuda taotlust','Изменить заявку')+'</button></div>':'<h2>'+tr('Registreeru praktikale','Записаться на практику')+'</h2><p class="muted">'+tr('Valitud pakett: ','Выбранный пакет: ')+'<strong>'+state.practice+'</strong></p><form id="practice-form" class="form-grid">'+field('practice-name',tr('Sinu nimi','Ваше имя'),'text','',true)+field('practice-email',tr('E-post','Email'),'email','',true)+field('practice-course',tr('Varasem koolitus või kogemus','Предыдущий курс или опыт'),'text','',false,'wide')+'<div class="field wide"><label for="practice-times">'+tr('Millised ajad sulle sobivad?','Какое время вам подходит?')+'</label><textarea id="practice-times" required placeholder="'+tr('Näiteks tööpäeva õhtud Pärnus','Например, вечера будних дней в Пярну')+'"></textarea></div><div class="wide notice">'+tr('See on aja kokkuleppimise taotlus. Kohtumine kinnitatakse pärast Maria vastust.','Это запрос на согласование времени. Встреча подтверждается после ответа Марии.')+'</div><button class="btn wide" type="submit">'+tr('Saada taotlus','Отправить заявку')+icon('arrow')+'</button></form>')+'</div></section>'}
function field(id,label,type='text',value='',required=true,cls=''){return '<div class="field '+cls+'"><label for="'+id+'">'+label+'</label><input id="'+id+'" name="'+id+'" type="'+type+'" value="'+esc(value)+'" '+(required?'required':'')+'></div>'}
function about(){return '<div class="page-head wrap"><div class="eyebrow">MS LAB</div><h1>'+tr('Teadmised. Täpsus.<br>Inimlik tugi.','Знания. Точность.<br>Человеческая поддержка.')+'</h1></div>'+teacher()+'<section class="section wrap"><div class="intro" style="padding:0"><div class="eyebrow">'+tr('Minu lähenemine','Мой подход')+'</div><div><h2>'+tr('Õpilase edu on meie eesmärk.','Успех ученика — наша цель.')+'</h2><p class="muted">'+tr('MS LAB ühendab teooria ja praktika. Õppimine jätkub ka pärast esimest koolituspäeva: saad oma tehnikat kinnistada individuaalpraktikas ning veebimaterjalide abil.','MS LAB объединяет теорию и практику. Обучение продолжается после первого дня: закрепляйте технику на индивидуальной практике и с помощью онлайн-материалов.')+'</p><div style="margin-top:30px">'+button(tr('Leia oma koolitus','Найти курс'),'/courses')+'</div></div></div></section>'}
function news(){return '<div class="page-head wrap"><div class="eyebrow">'+tr('MS LABi märkmik','Заметки MS LAB')+'</div><h1>'+tr('Mõtteid sinu teekonnale.','Идеи для вашего пути.')+'</h1><p>'+tr('Õppimisest, harjutamisest ja oma käekirja leidmisest.','Об обучении, практике и поиске своего почерка.')+'</p></div><section class="section wrap" style="padding-top:0"><div class="journal-grid news-full">'+articleCards()+'</div>'+sample()+'</section>'}
function article(id){const a=articles[Number(id)]||articles[0];return '<div class="page-head wrap"><div class="breadcrumb"><a href="#/news">'+tr('Uudised','Новости')+'</a> / '+a.date+'</div><h1 style="max-width:900px">'+tr(...a.title)+'</h1><p>MS LAB · '+tr('Näidisartikkel','Пример статьи')+'</p></div><article class="wrap section" style="padding-top:0"><img class="article-hero" src="assets/'+a.img+'" alt=""><div class="prose"><h2>'+tr('Alusta tugevast vundamendist.','Начните с прочной основы.')+'</h2><p>'+tr('Uue oskuse õppimine ei tähenda kõike korraga. Anna endale aega mõista iga tööetappi ning küsi, kui mõni detail jääb ebaselgeks.','Изучение нового навыка не требует всего и сразу. Дайте себе время понять каждый этап и задавайте вопросы, если что-то осталось неясным.')+'</p><h2>'+tr('Harjuta teadlikult.','Практикуйтесь осознанно.')+'</h2><p>'+tr('Koolituse järel aitab individuaalne tagasiside märgata seda, mis juba õnnestub, ja valida järgmise harjutuse. Pane kirja tekkinud küsimused ning aruta neid oma koolitajaga.','Индивидуальная обратная связь после курса помогает увидеть успехи и выбрать следующее упражнение. Запишите вопросы и обсудите их с преподавателем.')+'</p><div class="notice">'+tr('Prototüübi näidistekst. Lõplikud artiklid kirjutab ja kinnitab Maria.','Пример текста прототипа. Итоговые статьи пишет и утверждает Мария.')+'</div><div style="margin-top:30px">'+button(tr('Vaata praktikat','Посмотреть практику'),'/practice')+'</div></div></article>'}
function cartSummary(){let subtotal=state.cart.reduce((a,c)=>a+c.price,0),discount=state.couponApplied?subtotal*state.discount/100:0,total=Math.round((subtotal-discount)*100)/100;return '<aside class="checkout-summary"><h3>'+tr('Sinu valikud','Ваш выбор')+'</h3>'+state.cart.map((c,i)=>'<div class="cart-item"><img src="assets/'+course(c.id).image+'" alt=""><div><strong>'+name(c.id)+'</strong><small>'+fmt(c.format)+(c.format!=='online'?' · '+c.date:'')+'<br>ET · '+tr('Ligipääs 6 kuud (näidis)','Доступ 6 месяцев (пример)')+'</small><span class="text-small">'+money(c.price)+'</span></div><button class="icon-btn" data-action="remove-cart" data-index="'+i+'" aria-label="'+tr('Eemalda','Удалить')+'">'+icon('close')+'</button></div>').join('')+'<form class="coupon" id="coupon-form"><input id="coupon-code" aria-label="'+tr('Sooduskood','Промокод')+'" placeholder="'+tr('Sooduskood','Промокод')+'" value="'+esc(state.coupon)+'"><button class="btn small secondary" type="submit">'+tr('Rakenda','Применить')+'</button></form><p id="coupon-feedback" class="text-small" role="status">'+(state.couponApplied?tr('Kood rakendatud: −','Код применён: −')+state.discount+'%':'')+'</p><div class="total-row"><span>'+tr('Vahesumma','Подытог')+'</span><span>'+money(subtotal)+'</span></div>'+(state.couponApplied?'<div class="total-row"><span>'+tr('Soodustus','Скидка')+'</span><span>−'+money(discount)+'</span></div>':'')+'<div class="total-row grand"><span>'+tr('Kokku','Итого')+'</span><span>'+money(total)+'</span></div>'+(state.payment==='deposit'?'<div class="total-row"><span>'+tr('Tasud praegu (50%)','Сейчас (50%)')+'</span><strong>'+money(total/2)+'</strong></div><div class="total-row"><span>'+tr('Järelejäänud summa','Остаток')+'</span><span>'+money(total/2)+'</span></div><p class="text-small muted">'+tr('Näidistähtaeg: 7 päeva enne kontaktpäeva.','Пример срока: за 7 дней до очного занятия.')+'</p>':'')+sample()+'</aside>'}
function checkout(){if(state.checkout===3)return '<section class="section wrap"><div class="success-block card" style="max-width:700px;margin:auto"><div class="success-icon">✓</div><h2>'+tr('Sinu järgmine samm on tehtud.','Ваш следующий шаг сделан.')+'</h2><p class="muted">'+tr('Näidismakse on kinnitatud. Päris raha ei liigutatud ega e-kirja saadetud. Sinu näidiskoolitus on õppija vaates valmis.','Пример платежа подтверждён. Деньги не списаны, письмо не отправлено. Курс доступен в режиме ученика.')+'</p><div style="margin-top:28px">'+button(tr('Alusta õppimist','Начать обучение'),'/account')+'</div></div></section>';
if(!state.cart.length)return '<section class="section wrap"><div class="empty">'+icon('bag')+'<h2 style="margin:25px 0">'+tr('Sinu ostukorv ootab esimest sammu.','Ваша корзина ждёт первого шага.')+'</h2><p style="margin:0 auto 25px">'+tr('Vali koolitus, mis toetab sinu järgmist oskust.','Выберите курс для вашего следующего навыка.')+'</p>'+button(tr('Vaata koolitusi','Посмотреть курсы'),'/courses')+'</div></section>';
return '<div class="page-head wrap"><div class="breadcrumb"><a href="#/courses">'+tr('Koolitused','Курсы')+'</a> / '+tr('Ostukorv','Корзина')+'</div><h1>'+tr('Investeeri oma oskustesse.','Инвестируйте в свои навыки.')+'</h1></div><section class="wrap checkout-grid"><div><div class="steps">'+[tr('Sinu andmed','Ваши данные'),tr('Tasumine','Оплата'),tr('Kinnitus','Подтверждение')].map((s,i)=>'<span class="step '+(state.checkout===i?'active':'')+'"><b>'+(i+1)+'</b>'+s+'</span>').join('')+'</div>'+(state.checkout===0?'<form id="details-form"><h2 style="font-size:30px;margin-bottom:25px">'+tr('Kes tuleb õppima?','Кто будет учиться?')+'</h2><div class="form-grid">'+field('learner-name',tr('Õppija ees- ja perekonnanimi','Имя и фамилия ученика'),'text',state.learner.name||'')+field('learner-email',tr('Õppija e-post','Email ученика'),'email',state.learner.email||'')+'</div><h3 style="margin-top:35px">'+tr('Kellele koostame arve?','На кого оформить счёт?')+'</h3><div class="pills payer-type"><button type="button" class="pill '+(state.payer==='private'?'active':'')+'" data-action="payer" data-payer="private">'+tr('Eraisik','Частное лицо')+'</button><button type="button" class="pill '+(state.payer==='company'?'active':'')+'" data-action="payer" data-payer="company">'+tr('Ettevõte','Компания')+'</button></div>'+(state.payer==='company'?'<div class="form-grid">'+field('company-name',tr('Ettevõtte nimi','Название компании'),'text',state.learner.company||'')+field('company-code',tr('Registrikood','Регистрационный код'),'text',state.learner.companyCode||'')+field('company-vat',tr('KMKR number (valikuline)','Номер НДС (необязательно)'),'text',state.learner.vat||'',false)+field('invoice-email',tr('Arve e-post','Email для счёта'),'email',state.learner.invoiceEmail||'')+'</div>':'<p class="muted text-small">'+tr('Arve koostame õppija nimele.','Счёт оформим на имя ученика.')+'</p>')+'<div class="notice" style="margin-top:30px">'+tr('Prototüüp: kasuta väljamõeldud andmeid. Neid ei saadeta serverisse.','Прототип: используйте вымышленные данные. Они не отправляются на сервер.')+'</div><button class="btn" type="submit" style="margin-top:25px">'+tr('Jätka tasumisega','Перейти к оплате')+icon('arrow')+'</button></form>':state.checkout===1?'<form id="payment-form"><h2 style="font-size:30px;margin-bottom:25px">'+tr('Vali sobiv tasumine','Выберите способ оплаты')+'</h2><div class="payment-options"><label><input type="radio" name="payment" value="full" '+(state.payment==='full'?'checked':'')+'><span>'+tr('Tasun kogu summa','Оплатить полностью')+'<small>'+tr('100% koolituse maksumusest.','100% стоимости курса.')+'</small></span></label><label><input type="radio" name="payment" value="deposit" '+(state.payment==='deposit'?'checked':'')+'><span>'+tr('50% ettemaks','Предоплата 50%')+'<small>'+tr('Ülejäänu enne kontaktpäeva. Näidistingimus.','Остаток перед очным занятием. Пример условия.')+'</small></span></label></div><p class="text-small muted" style="margin:20px 0">'+tr('Järelmaks ilmub siis, kui teenusepakkuja selle lubab. Prototüübis pole see ühendatud.','Рассрочка появится при доступности у провайдера. В прототипе она не подключена.')+'</p><label class="check" style="margin:25px 0 17px"><input type="checkbox" required><span>'+tr('Olen tutvunud koolituse ja tasumise näidistingimustega.','Я ознакомился с примером условий курса и оплаты.')+'</span></label><label class="check"><input type="checkbox"><span>'+tr('Soovin saada MS LABi uudiskirju (valikuline).','Хочу получать рассылку MS LAB (необязательно).')+'</span></label><div class="row" style="margin-top:30px"><button type="button" class="btn secondary" data-action="checkout-back">'+tr('Tagasi','Назад')+'</button><button class="btn" type="submit">'+tr('Proovi Montonio makset','Попробовать оплату Montonio')+icon('arrow')+'</button></div></form>':'<div class="card success-block"><div class="success-icon">'+icon('clock')+'</div><h2>'+tr('Makse kinnitamisel','Ожидаем подтверждение')+'</h2><p class="muted">'+tr('Näidismakse ootab kinnitust. Päris teenuses kinnitab laekumise maksepakkuja.','Пример платежа ожидает подтверждения. В реальном сервисе платёж подтвердит провайдер.')+'</p><div class="stack" style="margin-top:25px"><button class="demo-action" data-action="payment-success">'+tr('Simuleeri edukat makset','Симулировать успешный платёж')+'</button><button class="demo-action" data-action="payment-fail">'+tr('Simuleeri ebaõnnestumist','Симулировать ошибку')+'</button></div></div>')+'</div>'+cartSummary()+'</section>'}
