function dashboard(){return '<section class="student-page"><div class="student-welcome"><div><div class="eyebrow">'+tr('Sinu õpiteekond','Ваше обучение')+'</div><h1>'+tr('Tere tagasi, Liis.','С возвращением, Лийс.')+'</h1><p class="muted">'+tr('Väikesed sammud viivad kindlate oskusteni.','Маленькие шаги ведут к уверенным навыкам.')+'</p></div>'+button(tr('Vaata kõiki koolitusi','Все курсы'),'/courses','secondary')+'</div><div class="dashboard-grid"><div class="continue-card dark"><div><span class="tag dark">'+tr('Pooleli','В процессе')+'</span><h2>'+name('brow')+'</h2><p>'+tr('Moodul 2 · Kulmukuju analüüs','Модуль 2 · Анализ формы бровей')+'</p><div class="progress"><span style="width:'+(state.watched?75:38)+'%"></span></div><div class="row between"><small>'+tr('Sinu areng','Ваш прогресс')+'</small><small>'+(state.watched?75:38)+'%</small></div><a class="btn light" style="margin-top:28px" href="#/lesson">'+tr('Jätka õppimist','Продолжить')+icon('play')+'</a><p style="margin-top:18px;font-size:10px">'+tr('Näidisligipääs kuni 14.05.2027','Пример доступа до 14.05.2027')+'</p></div><img src="assets/brow-editorial.png" alt=""></div><div class="dashboard-small"><div class="card">'+icon('calendar')+'<h3>'+tr('Kohtume kontaktpäeval','Увидимся на очном занятии')+'</h3><p class="text-small">14.11.2026 · 10:00–17:00<br>Tallinn</p><a class="link" href="#/calendar" style="margin-top:15px">'+tr('Vaata ajakava','Расписание')+icon('up')+'</a></div><div class="panel"><div class="row between"><span class="text-small">'+tr('Tasumata jääk','Остаток к оплате')+'</span><span class="tag rose">'+tr('Näidis','Пример')+'</span></div><div class="price" style="margin:12px 0">'+money(remaining())+'</div><button class="link" data-action="balance">'+tr('Tasu jääk','Оплатить остаток')+icon('up')+'</button></div></div></div><div class="dashboard-bottom"><div class="card">'+icon('award')+'<h3>'+tr('Sinu tunnistus','Ваше свидетельство')+'</h3><p>'+tr(state.assessed?'Tunnistus on valmis.':'Test ja praktiline hindamine ootavad läbimist.',state.assessed?'Свидетельство готово.':'Предстоят тест и оценка практики.')+'</p><a class="link" href="#/certificate">'+tr('Vaata tingimusi','Условия получения')+icon('up')+'</a></div><div class="card">'+icon('flower')+'<h3>'+tr('Harjutame koos','Практикуемся вместе')+'</h3><p>'+tr('MINI või MAXI — personaalne tugi sinu järgmisele sammule.','MINI или MAXI — поддержка вашего следующего шага.')+'</p><a class="link" href="#/practice">'+tr('Vali praktika','Выбрать практику')+icon('up')+'</a></div><div class="card">'+icon('book')+'<h3>'+tr('Sinu dokumendid','Ваши документы')+'</h3><p>'+tr('Õppematerjalid ja arved mugavalt ühes kohas.','Материалы и счета в одном месте.')+'</p><a class="link" href="#/invoices">'+tr('Vaata arveid','Посмотреть счета')+icon('up')+'</a></div></div>'+sample()+'</section>'}
function lesson(){if(state.sessionEnded)return '<section class="student-page"><div class="empty"><h2>'+tr('Sinu konto avati teises seadmes.','В ваш аккаунт вошли с другого устройства.')+'</h2><p style="margin:25px auto">'+tr('Seetõttu lõppes siin aktiivne seanss. Sinu õppejärg on alles.','Поэтому эта сессия завершилась. Ваш прогресс сохранён.')+'</p><button class="btn" data-action="restore-session">'+tr('Logi uuesti sisse (demo)','Войти снова (демо)')+'</button></div></section>';
return '<section class="wrap lesson-layout"><div><div class="breadcrumb"><a href="#/account">'+tr('Minu koolitused','Мои курсы')+'</a> / '+name('brow')+'</div><div class="video-frame"><img src="assets/brow-editorial.png" alt="'+tr('Videotunni näidis','Пример видеоурока')+'"><span class="video-caption">'+tr('Videopleieri prototüüp · Näidisõppija','Прототип плеера · Пример ученика')+'</span><button class="play-button" data-action="play-demo" aria-label="'+tr('Videopleieri demo','Демо плеера')+'">'+icon('play')+'</button><div class="video-controls"><div class="progress"><span style="width:'+(state.watched?100:38)+'%"></span></div><div class="row between"><div class="row"><button data-action="play-demo" aria-label="Play">'+icon('play')+'</button><small>'+(state.watched?'18:40':'07:12')+' / 18:40</small></div><div class="row"><button data-action="captions">CC</button><button data-action="speed">1×</button></div></div></div></div><div class="lesson-title"><div class="tags"><span class="tag">'+tr('Moodul 2','Модуль 2')+'</span><span class="tag">'+tr('Tund 2.3','Урок 2.3')+'</span></div><h1>'+tr('Kulmukuju analüüs ja tasakaal','Анализ формы бровей и баланс')+'</h1><p>'+tr('Õpi märkama näo proportsioone ja kavandama harmoonilist kulmukuju.','Учитесь замечать пропорции лица и планировать гармоничную форму бровей.')+'</p></div><div class="notice">'+(state.watched?tr('Videotund on näites läbitud. Järgmine moodul ja test on avatud.','В примере урок завершён. Следующий модуль и тест открыты.'):tr('Järgmine moodul avaneb, kui oled vaadanud vähemalt 95% videost ja jõudnud lõpuni. Näidisreegel.','Следующий модуль откроется после просмотра минимум 95% видео и его окончания. Пример правила.'))+'</div><div class="row" style="margin-top:25px;flex-wrap:wrap"><button class="demo-action" data-action="complete-video">'+tr('Simuleeri: video lõpuni vaadatud','Симулировать: видео просмотрено')+'</button><button class="demo-action" data-action="end-session">'+tr('Simuleeri uut sisselogimist','Симулировать новый вход')+'</button></div><div class="divider"></div><h3>'+tr('Õppematerjalid','Учебные материалы')+'</h3><button class="link" data-action="resource" style="margin-top:16px">'+icon('book')+tr('Kulmukuju analüüsi tööleht','Рабочий лист анализа бровей')+icon('up')+'</button></div><aside class="curriculum"><div class="curriculum-head"><h3>'+tr('Koolituse sisu','Содержание курса')+'</h3><div class="progress"><span style="width:'+(state.watched?75:38)+'%"></span></div><small class="muted">'+tr('Samm-sammult kindla tulemuseni.','Шаг за шагом к результату.')+'</small></div>'+[tr('Tere tulemast koolitusele','Добро пожаловать'),tr('Töövahendid ja hügieen','Инструменты и гигиена'),tr('Kulmukuju analüüs','Анализ формы бровей'),tr('Värviteooria ja praktika','Теория цвета и практика'),tr('Teadmiste kontroll','Проверка знаний')].map((n,i)=>'<button class="lesson-row '+(i===2?'active':'')+'" data-action="lesson-item" data-index="'+i+'" '+(i>2&&!state.watched?'aria-disabled="true"':'')+'><span class="state">'+(i<2?'✓':i===2?'▶':state.watched?'○':icon('lock'))+'</span><span>'+n+'<small>'+(i<2?tr('Läbitud','Завершено'):i===2?tr('Pooleli · 18 min','В процессе · 18 мин'):state.watched?tr('Avatud','Доступно'):tr('Lukus','Закрыто'))+'</small></span></button>').join('')+'<div style="padding:23px"><button class="btn full small" data-action="go-quiz" '+(!state.watched?'disabled':'')+'>'+tr('Alusta testi','Начать тест')+icon('arrow')+'</button></div></aside></section>'}
function quiz(){return '<section class="student-page"><div class="breadcrumb"><a href="#/lesson">'+tr('Tagasi õppetundi','Назад к уроку')+'</a> / '+tr('Test','Тест')+'</div><div class="quiz-box card"><span class="tag">'+tr('Teadmiste kontroll · näidistest','Проверка знаний · пример теста')+'</span>'+(state.quizPassed?'<div class="success-block"><div class="success-icon">✓</div><h2>'+tr('Hea töö! Test on läbitud.','Отлично! Тест пройден.')+'</h2><p class="muted">'+tr('Tulemus: 100%. Järgmine samm on praktilise töö hindamine koolitaja poolt.','Результат: 100%. Следующий шаг — оценка практики преподавателем.')+'</p><div style="margin-top:25px">'+button(tr('Vaata tunnistuse staatust','Статус свидетельства'),'/certificate')+'</div></div>':!state.watched?'<div class="empty"><h2>'+tr('Lõpeta esmalt videotund.','Сначала завершите видеоурок.')+'</h2><div style="margin-top:25px">'+button(tr('Tagasi tundi','К уроку'),'/lesson')+'</div></div>':'<form id="quiz-form"><h2>'+tr('Millest alustad kulmukuju kavandamist?','С чего начинается планирование формы бровей?')+'</h2><p class="muted text-small">'+tr('Küsimus 1 / 1 · Vali üks vastus.','Вопрос 1 / 1 · Выберите один ответ.')+'</p>'+[tr('Valin kõigile klientidele sama kulmukuju.','Выбираю одинаковую форму для всех клиентов.'),tr('Analüüsin kliendi näoproportsioone ja loomulikku kulmukuju.','Анализирую пропорции лица и естественную форму бровей.'),tr('Alustan kohe värvi pealekandmisest.','Сразу начинаю наносить краску.')].map((a,i)=>'<label class="answer"><input type="radio" name="answer" value="'+i+'" required>'+a+'</label>').join('')+'<p id="quiz-feedback" role="status" style="margin:15px 0"></p><button class="btn" type="submit">'+tr('Esita vastus','Отправить ответ')+icon('arrow')+'</button></form>')+'</div></section>'}
function certificate(){return '<section class="student-page"><div class="breadcrumb"><a href="#/account">'+tr('Minu koolitused','Мои курсы')+'</a> / '+tr('Tunnistus','Свидетельство')+'</div><div class="section-heading"><div><div class="eyebrow">'+tr('Sinu saavutused','Ваши достижения')+'</div><h1>'+tr('Üks oluline samm edasi.','Ещё один важный шаг.')+'</h1></div>'+(state.assessed?'<button class="btn" data-action="print">'+tr('Prindi / salvesta PDF','Печать / сохранить PDF')+'</button>':'')+'</div>'+(!state.assessed?'<div class="panel"><h3>'+tr('Tunnistus ootab hindamise lõpetamist.','Свидетельство ожидает завершения оценки.')+'</h3><ul class="check-list" style="margin:25px 0"><li>'+tr('Videotunnid','Видеоуроки')+': '+(state.watched?'✓':tr('pooleli','в процессе'))+'</li><li>'+tr('Test','Тест')+': '+(state.quizPassed?'✓':tr('ootab läbimist','не пройден'))+'</li><li>'+tr('Praktiline töö: ootab koolitaja kinnitust','Практика: ожидает подтверждения преподавателя')+'</li></ul><a class="btn secondary" href="#/lesson">'+tr('Jätka õppimist','Продолжить обучение')+'</a></div>':'<div class="certificate"><small>MS LAB KOOLITUSKESKUS · '+tr('NÄIDISDOKUMENT','ПРИМЕР ДОКУМЕНТА')+'</small><h1>'+tr('Tunnistus','Свидетельство')+'</h1><p>'+name('brow')+'</p><h2>Liis Kask</h2><p>'+tr('on läbinud koolituse ning sooritanud näidistesti ja praktilise hindamise.','прошла обучение и выполнила пример теста и практической оценки.')+'</p><div class="certificate-meta"><span>MS LAB<br>DEMO-2026-001</span><span>Maria Sosnina<br>14.11.2026 · Tallinn</span></div><small style="margin-top:25px">'+tr('Disaininäidis. Ei ole kehtiv haridusdokument.','Пример дизайна. Не является действительным документом об образовании.')+'</small></div>')+sample()+'</section>'}
